import hashlib,json,subprocess,sys,tarfile,time
from pathlib import Path
out=Path(sys.argv[1]); out.mkdir(parents=True,exist_ok=False)
paths=sorted([p for name in ['hyperreal','hyperlimit','hypercurve','hyperdrc'] for p in Path('crates',name).rglob('*') if p.is_file() and 'target' not in p.parts and (p.suffix=='.rs' or p.name in ['Cargo.toml','Cargo.lock'])]+[Path('Cargo.toml'),Path('Cargo.lock')])
def hashes(): return {str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}
initial=hashes()
with tarfile.open(out/'sources.tar.gz','w:gz') as archive:
    for p in paths: archive.add(p,arcname=str(p))
(out/'sources.json').write_text(json.dumps({'source_hashes':initial,'unchanged':True},indent=2)+'\n')
commands=[('focused-bbox-unit', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'bbox::tests::', '--', '--test-threads=1']), ('focused-bbox-integration', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--test', 'hypercurve_bbox', '--', '--test-threads=1']), ('focused-policy-budgets', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'policy::budget_tests::', '--', '--test-threads=1']), ('focused-cached-operand-order', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'cached_interval_tests::', '--', '--test-threads=1']), ('focused-native-contour-winding', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'contour::tests::', '--', '--test-threads=1']), ('focused-contour-integration', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--test', 'hypercurve_contour', '--', '--test-threads=1']), ('focused-native-winding-reuse', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'native_winding_reuse', '--', '--test-threads=1']), ('focused-materialized-winding-jump', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'materialized_single_boundary_windings_match_two_rays', '--', '--test-threads=1']), ('retained-circle-support-regressions', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'retained_circle_support', '--', '--test-threads=1']), ('focused-circular-arc-recovery', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'arc_bezier::', '--', '--test-threads=1']), ('focused-injectivity-certificates', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'injectivity_certificates_own_their_domain_and_circle_chart', '--', '--test-threads=1']), ('focused-tangent-order', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'retained_and_represented_tangents_share_filled_face_order', '--', '--test-threads=1']), ('focused-boundary-tangents', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'boundary_tangent', '--', '--test-threads=1']), ('focused-boundary-side-rays', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'boundary_side_rays', '--', '--test-threads=1']), ('focused-affine-chart', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'retained_affine_line_chart', '--', '--test-threads=1']), ('focused-region-boolean', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--test', 'hypercurve_curve_region_boolean', '--', '--test-threads=1']), ('focused-line-support', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'retained_delta_tests', '--', '--test-threads=2']), ('focused-line-intersections', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--lib', 'intersect::', '--', '--test-threads=2']), ('focused-fit-stroke', ['cargo', 'test', '--locked', '-p', 'hypercurve', '--release', '--test', 'hypercurve_bezier_fit_offset', '--test', 'native_linear_stroke', '--test', 'hypercurve_curve_region_stroke', '--', '--test-threads=2']), ('focused-drc', ['cargo', 'test', '--locked', '-p', 'hyperdrc', '--release', '--test', 'native_linear_strokes', '--', '--test-threads=2']), ('full-board-smoke', ['cargo', 'test', '--locked', '-p', 'hyperdrc', '--release', '--lib', 'zz_complex_project_performance_tests::kicad_board_completes_smoke_check_suite', '--', '--exact', '--test-threads=1'])]
status=[]
for name,command in commands:
    assert hashes()==initial
    started=time.monotonic()
    with (out/(name+'.log')).open('w') as log:
        code=subprocess.run(command,stdout=log,stderr=subprocess.STDOUT).returncode
    status.append({'name':name,'command':command,'exit_code':code,'elapsed_seconds':time.monotonic()-started})
    (out/'status.json').write_text(json.dumps(status,indent=2)+'\n')
    (out/'sources.json').write_text(json.dumps({'source_hashes':initial,'unchanged':initial==hashes()},indent=2)+'\n')
    assert initial==hashes()
    print(out,name,code,flush=True)
    if code: break
sys.exit(code)
